-- ---- Strict post-condition guard (all-or-nothing) -------------------------
CREATE TEMP TABLE _mig0041_post (ok INTEGER CHECK (ok = 1));

-- (a) manufacturers count = 156 + 84 = 240
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM manufacturers
) = 240 THEN 1 ELSE 0 END;

-- (b) sources count = 97 + 1 = 98
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM sources
) = 98 THEN 1 ELSE 0 END;

-- (c) Hikvision 209 aliases contains all 6 new tokens (case-insensitive)
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM manufacturers
     WHERE id = 209
       AND aliases LIKE '%EZVIZ%' COLLATE NOCASE
       AND aliases LIKE '%HiLook%' COLLATE NOCASE
       AND aliases LIKE '%Hikmicro%' COLLATE NOCASE
       AND aliases LIKE '%HiWatch%' COLLATE NOCASE
       AND aliases LIKE '%Annke%' COLLATE NOCASE
       AND aliases LIKE '%LaView%' COLLATE NOCASE
) = 1 THEN 1 ELSE 0 END;

-- (d) Amcrest (298) + Lorex (303) parent = 208; Speco (308) parent IS NULL
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM manufacturers
     WHERE (id = 298 AND parent_manufacturer_id = 208)
        OR (id = 303 AND parent_manufacturer_id = 208)
        OR (id = 308 AND parent_manufacturer_id IS NULL)
) = 3 THEN 1 ELSE 0 END;

-- (e) Exactly 52 new SPOKE rows under Hikvision 209
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM manufacturers
     WHERE parent_manufacturer_id = 209
       AND is_arm = 1
       AND query_default = 'hidden_arm'
       AND json_extract(notes, '$.ipvm_dispatch_ref') = 'MAC-533'
) = 52 THEN 1 ELSE 0 END;

-- (f) Exactly 32 new SPOKE rows under Dahua 208
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM manufacturers
     WHERE parent_manufacturer_id = 208
       AND is_arm = 1
       AND query_default = 'hidden_arm'
       AND json_extract(notes, '$.ipvm_dispatch_ref') = 'MAC-533'
) = 32 THEN 1 ELSE 0 END;

-- (g) Identifiers UNCHANGED — total 43848, active 43132
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM identifiers
) = 43848 THEN 1 ELSE 0 END;
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM identifiers WHERE superseded_by IS NULL
) = 43116 THEN 1 ELSE 0 END;

-- (h) Exactly one new sources row (the IPVM one) — verify url uniqueness
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM sources
     WHERE url = 'https://ipvm.com/reports/hikvision-oem-directory'
) = 1 THEN 1 ELSE 0 END;

-- (i) schema_version stays at 33 (data-only migration; no version bump)
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT MAX(version) FROM schema_version
) = 33 THEN 1 ELSE 0 END;

-- (j) FK integrity post-check — verify every MAC-533 spoke row's parent_manufacturer_id points at a real hub
--     (json_valid filter first to skip pre-existing rows with malformed-JSON notes — §11 #17 precedent)
INSERT INTO _mig0041_post(ok) SELECT CASE WHEN (
    SELECT COUNT(*) FROM manufacturers m
     WHERE json_valid(m.notes) = 1
       AND m.is_arm = 1
       AND m.query_default = 'hidden_arm'
       AND json_extract(m.notes, '$.ipvm_dispatch_ref') = 'MAC-533'
       AND NOT EXISTS (
         SELECT 1 FROM manufacturers h
          WHERE h.id = m.parent_manufacturer_id
            AND h.is_arm = 0
            AND h.query_default = 'visible'
       )
) = 0 THEN 1 ELSE 0 END;

DROP TABLE _mig0041_pre;
DROP TABLE _mig0041_post;

COMMIT;
